let currentlyPlayingId: string | null = null;
let currentAudio: HTMLAudioElement | null = null;
const onPlay = (item) => {
  if (currentAudio) { currentAudio.pause(); currentAudio = null; }
  currentlyPlayingId = null;
  if (item.url) {
    currentAudio = new Audio(item.url);
    currentlyPlayingId = item.id;
    currentAudio.addEventListener('ended', () => { currentlyPlayingId = null; renderAudioPanel(); });
    currentAudio.play();
  }
  renderAudioPanel();
};
// renderAudioPanel reads currentlyPlayingId and sets play/pause icon + highlight class per item
